  for(const key of ["alarm_information_1","alarm_information_2"]){let previous=0;for(const row of metrics.get(key)||[]){const raw=Math.trunc(row.raw??row.value),rising=raw&~previous,falling=previous&~raw;previous=raw;if(row.time<state.start||row.time>state.end)continue;const definitions=ALARM_BITS[key]||{};for(const [bitText,description] of Object.entries(definitions)){const bit=Number(bitText),mask=1<<bit;if(rising&mask)events.push({...row,key,severity:"warning",code:`bit ${bit} active`,description});if(falling&mask)events.push({...row,key,severity:"recovery",code:`bit ${bit} cleared`,description:`${description} cleared`});}}}
